-- =============================================================================
-- Stratos — the help centre in English and German
--
--   1. `help_articles.translations`: {"en": {question, answer, topic,
--      alt_questions}, "de": {…}}. Hungarian stays the article itself; a
--      language with no entry shows the Hungarian text.
--   2. `client_help_articles()` also returns the translations, so the client
--      assistant answers in the language the client chose.
--   3. The 74 seeded articles get English and German:
--        * 60 from the website's own published English and German FAQ
--          (_build/i18n — the same answers the site shows), with German in the
--          site's informal "du";
--        * 14 client-portal articles translated here, naming the portal's
--          buttons exactly as the translated portal does.
--      An article gets them ONLY if its Hungarian question and answer are still
--      exactly the seeded text and it has no translation yet — an article
--      edited in the Portal keeps its edit and is translated there.
--
-- Nothing is deleted. Re-runnable. Run after 20261009000100_profile_locale.sql.
-- =============================================================================

alter table help_articles add column if not exists translations jsonb not null default '{}'::jsonb;

-- The shape, in the database: only en/de, each with a question, an answer and
-- a topic within the Hungarian columns' limits, and at most 40 alternatives.
create or replace function help_translations_valid(tr jsonb) returns boolean
  language sql immutable set search_path = public
as $$
  select jsonb_typeof(tr) = 'object'
     and not exists (select 1 from jsonb_object_keys(tr) k where k not in ('en', 'de'))
     and not exists (
       select 1 from jsonb_each(tr) e
       where jsonb_typeof(e.value) <> 'object'
          or length(btrim(coalesce(e.value->>'question', ''))) not between 3 and 300
          or length(btrim(coalesce(e.value->>'answer', ''))) not between 1 and 4000
          or length(btrim(coalesce(e.value->>'topic', ''))) not between 1 and 80
          or (e.value ? 'alt_questions' and (jsonb_typeof(e.value->'alt_questions') <> 'array'
                                             or jsonb_array_length(e.value->'alt_questions') > 40)))
$$;

do $$ begin
  alter table help_articles add constraint help_articles_translations_check
    check (help_translations_valid(translations));
exception when duplicate_object then null; end $$;

comment on column help_articles.translations is
  'English and German: {"en": {question, answer, topic, alt_questions}, "de": {…}}. A missing language shows the Hungarian.';

-- Same as 20261004000100, plus the translations. The return type grows, so it
-- is dropped and recreated; its grants are re-applied below.
drop function if exists client_help_articles();
create function client_help_articles()
returns table (article_id uuid, question text, answer text, topic text, alt_questions text[], translations jsonb)
  language sql stable security definer set search_path = public as $$
  select h.id, h.question, h.answer, h.topic, h.alt_questions, h.translations
  from help_articles h
  where h.status = 'published' and client_account_id() is not null
  order by h.topic, h.position, h.question
$$;

do $$
begin
  execute 'revoke all on function client_help_articles() from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function client_help_articles() from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'grant execute on function client_help_articles() to authenticated';
  end if;
end $$;

-- The seeded articles' translations (slug, Hungarian question, Hungarian
-- answer as seeded, translations).
update help_articles h
   set translations = s.tr
  from (values
  ('web-branding-1', 'Mi tartozik pontosan a brandépítéshez — csak egy logót kapok?', 'Jóval több egy logónál — a teljes vizuális identitást felépítjük: logó, színvilág, betűtípusok, képi stílus és a hangnem, ahogy kommunikálsz. A logó csak a legláthatóbb darab; az érték az, hogy mindez egységes rendszerré áll össze, amit bárhol felismernek.', '{"en": {"question": "What exactly does brand building include — do I just get a logo?", "answer": "Far more than a logo — we build the whole visual identity: logo, colour world, typefaces, image style and the tone you communicate in. The logo is just the most visible piece; the value is that all of it becomes one coherent system people recognise anywhere.", "topic": "Branding and identity", "alt_questions": []}, "de": {"question": "Was genau umfasst Markenaufbau — bekomme ich nur ein Logo?", "answer": "Deutlich mehr als ein Logo — wir bauen die gesamte visuelle Identität: Logo, Farbwelt, Schriften, Bildsprache und die Tonalität deiner Kommunikation. Das Logo ist nur der sichtbarste Teil; der Wert liegt darin, dass all das zu einem einheitlichen System wird, das überall wiedererkannt wird.", "topic": "Branding und Markenidentität", "alt_questions": []}}'::jsonb),
  ('web-branding-2', 'Mi a különbség egy logó és egy komplett arculat között?', 'A logó egyetlen jel, az arculat egy teljes rendszer: logó, színek, tipográfia és használati szabályok együtt, minden felületen egységesen. Ha csak logód van, a névjegyed, a weboldalad és a posztjaid könnyen három külön cégnek tűnnek.', '{"en": {"question": "What''s the difference between a logo and a complete identity?", "answer": "A logo is a single mark; an identity is a whole system: logo, colours, typography and usage rules together, consistent on every surface. If all you have is a logo, your business card, website and posts easily look like three separate companies.", "topic": "Branding and identity", "alt_questions": []}, "de": {"question": "Was ist der Unterschied zwischen einem Logo und einem kompletten Erscheinungsbild?", "answer": "Ein Logo ist ein einzelnes Zeichen, ein Erscheinungsbild ein ganzes System: Logo, Farben, Typografie und Anwendungsregeln zusammen, auf jeder Fläche einheitlich. Hast du nur ein Logo, wirken Visitenkarte, Website und Posts leicht wie drei verschiedene Firmen.", "topic": "Branding und Markenidentität", "alt_questions": []}}'::jsonb),
  ('web-branding-3', 'Már van arculatom — érdemes újratervezni, vagy elég ráépíteni?', 'Attól függ, mennyire erős a meglévő alap. Ha van egy jól működő logód és színvilágod, sokszor elég ráépíteni és rendszerbe foglalni. Ha viszont széttartó vagy elavult, az újratervezés hosszú távon többet hoz. Az első lépés mindig egy őszinte átnézés.', '{"en": {"question": "I already have an identity — is a redesign worth it, or is building on it enough?", "answer": "It depends how strong the existing base is. If your logo and colours work well, extending them into a system is often enough. If it''s fragmented or dated, a redesign pays off more in the long run. The first step is always an honest review.", "topic": "Branding and identity", "alt_questions": []}, "de": {"question": "Ich habe schon ein Erscheinungsbild — lohnt ein Redesign, oder reicht Weiterbauen?", "answer": "Das hängt davon ab, wie stark die vorhandene Basis ist. Funktionieren Logo und Farben gut, reicht oft ein Ausbau zum System. Ist alles uneinheitlich oder veraltet, bringt ein Redesign langfristig mehr. Erster Schritt ist immer eine ehrliche Bestandsaufnahme.", "topic": "Branding und Markenidentität", "alt_questions": []}}'::jsonb),
  ('web-branding-4', 'Hogyan megy a brandépítés díjazása?', 'A brandépítés is a havidíjas modellben fut, így nem kell egyben kifizetned egy komplett arculat árát. A pontos konstrukciót mindig előre, átláthatóan tisztázzuk, meglepetések nélkül. Sok esetben a brandépítés összekapcsolható a weboldalas és marketinges szolgáltatással.', '{"en": {"question": "How is brand building charged?", "answer": "Brand building also runs on the monthly model, so you don''t pay for a complete identity in one lump. We always clarify the exact terms up front and transparently, with no surprises. In many cases branding can be combined with the website and marketing services.", "topic": "Branding and identity", "alt_questions": []}, "de": {"question": "Wie wird der Markenaufbau abgerechnet?", "answer": "Auch der Markenaufbau läuft im Monatsmodell, du zahlst ein komplettes Erscheinungsbild also nicht auf einen Schlag. Die genauen Konditionen klären wir immer vorab und transparent, ohne Überraschungen. Oft lässt sich Branding mit Website- und Marketingleistungen kombinieren.", "topic": "Branding und Markenidentität", "alt_questions": []}}'::jsonb),
  ('web-branding-5', 'Mennyi idő alatt készül el egy teljes arculat, és mit kell hozzá megadnom?', 'Jellemzően néhány hét, attól függően, milyen gyorsan érkeznek a visszajelzéseid. Tőled arra van szükségünk, hogy megismerjük a vállalkozásod: kik az ügyfeleid, mi a küldetésed, mi különböztet meg.', '{"en": {"question": "How long does a full identity take, and what do I need to provide?", "answer": "Typically a few weeks, depending on how quickly your feedback comes back. What we need from you is to get to know your business: who your clients are, what your mission is, what sets you apart.", "topic": "Branding and identity", "alt_questions": []}, "de": {"question": "Wie lange dauert ein vollständiges Erscheinungsbild, und was muss ich liefern?", "answer": "In der Regel einige Wochen, je nachdem, wie schnell dein Feedback kommt. Von dir brauchen wir, dass wir dein Unternehmen kennenlernen: wer deine Kunden sind, was deine Mission ist, was dich unterscheidet.", "topic": "Branding und Markenidentität", "alt_questions": []}}'::jsonb),
  ('web-branding-6', 'Kapok-e brand guide-ot a logó, színek és betűtípusok használatáról?', 'Igen — arculati útmutató is jár hozzá, ami rögzíti a logó helyes verzióit, a pontos színkódokat, a betűtípusokat és a képi stílus szabályait. Így bárki, aki neked dolgozik, egységesen tudja használni a márkádat.', '{"en": {"question": "Do I get a brand guide covering logo, colour and typeface usage?", "answer": "Yes — a brand guide is included, setting out the correct logo versions, exact colour codes, typefaces and image style rules. So anyone working for you can use your brand consistently.", "topic": "Branding and identity", "alt_questions": []}, "de": {"question": "Bekomme ich einen Brand Guide zu Logo, Farben und Schriften?", "answer": "Ja — ein Brand Guide gehört dazu und hält die korrekten Logoversionen, exakten Farbcodes, Schriften und Regeln der Bildsprache fest. So kann jeder, der für dich arbeitet, deine Marke einheitlich einsetzen.", "topic": "Branding und Markenidentität", "alt_questions": []}}'::jsonb),
  ('web-branding-7', 'Miért fontos a tudatos brandépítés egy kis cégnek?', 'A jó szolgáltatás alap, de önmagában nem látszik — a brand mondja el a világnak, hogy jó vagy, még mielőtt kipróbálnának. Egy profi arculattal a nagyokkal egy szinten jelensz meg. Nem luxus, hanem az egyik legjobb befektetés abba, hogy téged válasszanak.', '{"en": {"question": "Why does deliberate brand building matter for a small company?", "answer": "Good service is the baseline, but on its own it''s invisible — the brand tells the world you''re good before anyone has tried you. With a professional identity you appear on the same level as the big players. It isn''t a luxury; it''s one of the best investments in being the one they choose.", "topic": "Branding and identity", "alt_questions": []}, "de": {"question": "Warum ist bewusster Markenaufbau für kleine Firmen wichtig?", "answer": "Guter Service ist die Grundlage, bleibt aber allein unsichtbar — die Marke sagt der Welt, dass du gut bist, bevor dich jemand ausprobiert hat. Mit einem professionellen Erscheinungsbild trittst du auf Augenhöhe mit den Großen auf. Kein Luxus, sondern eine der besten Investitionen darin, gewählt zu werden.", "topic": "Branding und Markenidentität", "alt_questions": []}}'::jsonb),
  ('web-branding-8', 'Beleszólhatok a kreatív folyamatba, vagy ti döntitek el?', 'A márka a tiéd, ezért végig közös munka — nem teszünk le eléd egy kész logót, hogy „tessék, ez lettél". Az elején megismerünk, a kulcspontokon egyeztetünk, és a visszajelzéseid alakítják az irányt.', '{"en": {"question": "Can I have a say in the creative process, or do you decide?", "answer": "The brand is yours, so it''s collaborative throughout — we don''t drop a finished logo in front of you and say “there, that''s you now”. We get to know you at the start, check in at the key points, and your feedback shapes the direction.", "topic": "Branding and identity", "alt_questions": []}, "de": {"question": "Kann ich beim kreativen Prozess mitreden, oder entscheidet ihr?", "answer": "Die Marke gehört dir, deshalb arbeiten wir durchgehend gemeinsam — wir legen dir kein fertiges Logo hin mit den Worten „so, das bist du jetzt“. Am Anfang lernen wir dich kennen, an den Schlüsselpunkten stimmen wir uns ab, und dein Feedback formt die Richtung.", "topic": "Branding und Markenidentität", "alt_questions": []}}'::jsonb),
  ('web-branding-9', 'Össze lesz hangolva a brand a weboldalammal és a hirdetéseimmel?', 'Épp ez a lényeg: a brand a fonál, ami mindent összeköt. Ugyanaz a csapat építi az arculatot, a weboldalt és kezeli a hirdetéseket, így ezek nem külön szigetek. A látogató ugyanazt a színvilágot, hangnemet és élményt kapja a hirdetéstől a kapcsolatfelvételig.', '{"en": {"question": "Will the brand be aligned with my website and my ads?", "answer": "That''s exactly the point: the brand is the thread that ties everything together. The same team builds the identity and the website and runs the ads, so they aren''t separate islands. Visitors get the same colours, tone and experience from the ad through to getting in touch.", "topic": "Branding and identity", "alt_questions": []}, "de": {"question": "Wird die Marke auf Website und Werbung abgestimmt?", "answer": "Genau darum geht es: Die Marke ist der Faden, der alles verbindet. Dasselbe Team baut Erscheinungsbild und Website und betreut die Werbung — keine getrennten Inseln. Besucher erleben von der Anzeige bis zur Kontaktaufnahme dieselben Farben, dieselbe Tonalität, dasselbe Gefühl.", "topic": "Branding und Markenidentität", "alt_questions": []}}'::jsonb),
  ('web-branding-10', 'Mi történik a kész arculati fájlokkal — szabadon használhatom bárhol?', 'A kész arculat a tiéd — megkapod a szükséges fájlokat a megfelelő formátumokban, hogy bárhol használhasd: nyomdában, közösségi médiában, hirdetésen vagy a weboldaladon. Nem tartunk fogva a saját márkáddal.', '{"en": {"question": "What happens to the finished identity files — can I use them anywhere?", "answer": "The finished identity is yours — you receive the files you need in the right formats so you can use them anywhere: in print, on social media, in ads or on your website. We don''t hold you hostage with your own brand.", "topic": "Branding and identity", "alt_questions": []}, "de": {"question": "Was passiert mit den fertigen Dateien — darf ich sie überall nutzen?", "answer": "Das fertige Erscheinungsbild gehört dir — du erhältst die nötigen Dateien in den passenden Formaten, für Druck, Social Media, Anzeigen oder deine Website. Wir halten dich nicht mit deiner eigenen Marke fest.", "topic": "Branding und Markenidentität", "alt_questions": []}}'::jsonb),
  ('web-hirdeteskezeles-1', 'Mennyi hirdetési kerettel érdemes indulni, és ez hogyan viszonyul a kezelési díjhoz?', 'Két külön tételről van szó: a hirdetési keret, amit a Google vagy a Meta kap, és a kezelési díj, amit mi kapunk a munkáért. A legtöbb kis- és középvállalkozásnak havi 80–150 ezer forintos kerettel már érdemes indulni — ez alatt nehéz elég adatot gyűjteni az optimalizáláshoz. Az induló keretet mindig a piacodhoz és a céljaidhoz szabjuk.', '{"en": {"question": "What ad budget should I start with, and how does that relate to the management fee?", "answer": "These are two separate items: the ad budget, which goes to Google or Meta, and the management fee, which we receive for the work. Most small and medium businesses can start meaningfully at €200–400 a month — below that it''s hard to gather enough data to optimise. We always fit the starting budget to your market and your goals.", "topic": "Ads management", "alt_questions": []}, "de": {"question": "Mit welchem Werbebudget sollte ich starten, und wie verhält es sich zur Betreuungsgebühr?", "answer": "Das sind zwei getrennte Posten: das Werbebudget, das an Google oder Meta geht, und die Betreuungsgebühr für unsere Arbeit. Die meisten kleinen und mittleren Unternehmen können sinnvoll mit 200–400 € pro Monat starten — darunter ist es schwer, genug Daten zur Optimierung zu sammeln. Das Startbudget richten wir immer nach deinem Markt und deinen Zielen.", "topic": "Werbeanzeigen", "alt_questions": []}}'::jsonb),
  ('web-hirdeteskezeles-2', 'Mikor látok először eredményt?', 'A hirdetés az egyetlen csatorna, ahol lényegében a bekapcsolás napján jöhetnek az első érdeklődők. Az érdemi eredményhez viszont idő kell: az első 2–4 hét tanulási és adatgyűjtési szakasz, innentől optimalizálunk élesben. Reális elvárás, hogy 4–6 hét után már látszik a stabil irány.', '{"en": {"question": "When will I see the first results?", "answer": "Advertising is the only channel where the first enquiries can arrive essentially on the day you switch it on. Meaningful results take longer: the first 2–4 weeks are a learning and data-gathering phase, after which we optimise live. A realistic expectation is that the stable direction is visible after 4–6 weeks.", "topic": "Ads management", "alt_questions": []}, "de": {"question": "Wann sehe ich die ersten Ergebnisse?", "answer": "Werbung ist der einzige Kanal, bei dem die ersten Anfragen praktisch am Tag der Aktivierung kommen können. Belastbare Ergebnisse brauchen länger: Die ersten 2–4 Wochen sind Lern- und Datensammelphase, danach optimieren wir im laufenden Betrieb. Realistisch zeigt sich die stabile Richtung nach 4–6 Wochen.", "topic": "Werbeanzeigen", "alt_questions": []}}'::jsonb),
  ('web-hirdeteskezeles-3', 'Google Ads vagy Meta hirdetés éri meg jobban a vállalkozásomnak?', 'Attól függ, hogy az ügyfeled keres-e rád, vagy neked kell megtalálnod őt. A Google Ads a keresleti csatorna: aki beírja, hogy „vízszerelő Győr”, az venni akar. A Meta a kereslet-teremtő csatorna: ott te szólítod meg a felhasználót a hírfolyamban. Sok vállalkozásnak a kettő kombinációja hozza a legjobb eredményt.', '{"en": {"question": "Which is better for my business — Google Ads or Meta?", "answer": "It depends on whether your client searches for you or you have to find them. Google Ads is the demand channel: someone typing “plumber near me” intends to buy. Meta is the demand-generation channel: there you approach the user in their feed. For many businesses the combination performs best.", "topic": "Ads management", "alt_questions": []}, "de": {"question": "Was lohnt sich für mein Unternehmen mehr — Google Ads oder Meta?", "answer": "Das hängt davon ab, ob dein Kunde nach dir sucht oder ob du ihn finden musst. Google Ads ist der Nachfragekanal: Wer „Klempner in der Nähe“ eingibt, will kaufen. Meta ist der Nachfrage schaffende Kanal: Dort sprichst du den Nutzer im Feed an. Für viele Unternehmen bringt die Kombination das beste Ergebnis.", "topic": "Werbeanzeigen", "alt_questions": []}}'::jsonb),
  ('web-hirdeteskezeles-4', 'Honnan tudom, hogy megtérül a hirdetés — mit és hogyan mértek?', 'Nem a lájkokat és a megjelenéseket nézzük, hanem az üzleti eredményt. Konverziómérést állítunk be: hány ajánlatkérés, hívás, űrlapkitöltés vagy vásárlás jött a hirdetésből, és az mennyibe került. Ezt havi riportban átlátható formában kapod meg.', '{"en": {"question": "How do I know the advertising pays off — what do you measure and how?", "answer": "We don''t watch likes and impressions, we watch business results. We set up conversion tracking: how many quote requests, calls, form submissions or purchases came from the ads, and what each cost. You get it in a clear monthly report.", "topic": "Ads management", "alt_questions": []}, "de": {"question": "Woher weiß ich, dass sich Werbung rechnet — was messt ihr und wie?", "answer": "Wir schauen nicht auf Likes und Impressionen, sondern auf das Geschäftsergebnis. Wir richten Conversion-Tracking ein: wie viele Angebotsanfragen, Anrufe, Formulareinsendungen oder Käufe aus der Werbung kamen und was sie gekostet haben. Das bekommst du übersichtlich im Monatsreport.", "topic": "Werbeanzeigen", "alt_questions": []}}'::jsonb),
  ('web-hirdeteskezeles-5', 'Mi történik a hirdetési fiókkal, ha felmondom a szerződést?', 'A hirdetési fiók a tiéd marad — ez nálunk alapelv. A kampányokat mindig a te saját Google Ads és Meta fiókodban építjük fel, amihez mi kezelői hozzáférést kapunk, nem fordítva. Ha bármikor elválnak útjaink, a fiók, az adatok és a felépített kampányok mind veled maradnak.', '{"en": {"question": "What happens to the ad account if I cancel?", "answer": "The ad account stays yours — that''s a principle for us. We always build campaigns inside your own Google Ads and Meta accounts, to which we get manager access, not the other way round. If our paths ever part, the account, the data and the campaigns all stay with you.", "topic": "Ads management", "alt_questions": []}, "de": {"question": "Was passiert mit dem Werbekonto, wenn ich kündige?", "answer": "Das Werbekonto bleibt deins — das ist bei uns Grundsatz. Kampagnen bauen wir immer in deinen eigenen Google-Ads- und Meta-Konten auf, zu denen wir Verwalterzugriff erhalten, nicht umgekehrt. Trennen sich unsere Wege, bleiben Konto, Daten und Kampagnen bei dir.", "topic": "Werbeanzeigen", "alt_questions": []}}'::jsonb),
  ('web-hirdeteskezeles-6', 'Miért fizetek havidíjat a kezelésért, ha úgyis a Google/Meta kapja a hirdetési összeget?', 'Mert a platform csak egy eszköz — a pénzed elköltésének módja dönti el, hogy megtérül-e. Egy rosszul beállított kampány pontosan ugyanúgy elviszi a keretedet, csak eredmény nélkül. A kezelési díjért mi végezzük a valódi munkát: célközönség-kutatás, hirdetésszövegek, kreatívok, licitstratégia, folyamatos optimalizálás és mérés.', '{"en": {"question": "Why pay a monthly management fee if Google/Meta gets the ad spend anyway?", "answer": "Because the platform is only a tool — how the money is spent decides whether it pays off. A badly set-up campaign burns through your budget just as fast, only without results. The management fee covers the actual work: audience research, ad copy, creative, bidding strategy, continuous optimisation and measurement.", "topic": "Ads management", "alt_questions": []}, "de": {"question": "Warum zahle ich eine monatliche Betreuungsgebühr, wenn das Werbebudget ohnehin an Google/Meta geht?", "answer": "Weil die Plattform nur ein Werkzeug ist — wie das Geld ausgegeben wird, entscheidet über die Rendite. Eine schlecht aufgesetzte Kampagne verbrennt dein Budget genauso schnell, nur ohne Ergebnis. Die Betreuungsgebühr deckt die eigentliche Arbeit: Zielgruppenrecherche, Anzeigentexte, Kreation, Gebotsstrategie, laufende Optimierung und Messung.", "topic": "Werbeanzeigen", "alt_questions": []}}'::jsonb),
  ('web-hirdeteskezeles-7', 'Kell hozzá kész weboldal, vagy elég egy Facebook-oldal is?', 'Kell egy hely, ahová a hirdetés vezet, és ahol az érdeklődő döntést tud hozni. A legjobb egy erre kihegyezett landing oldal vagy jól felépített weboldal, mert ott te irányítod az élményt és tudsz mérni. Ha nincs megfelelő oldalad, nálunk a weboldal és a hirdetés egy kézben van.', '{"en": {"question": "Do I need a finished website, or is a Facebook page enough?", "answer": "You need somewhere the ad leads to, where the prospect can make a decision. A purpose-built landing page or a well-structured website is best, because there you control the experience and can measure. If you don''t have a suitable site, with us the website and the advertising come from one team.", "topic": "Ads management", "alt_questions": []}, "de": {"question": "Brauche ich eine fertige Website, oder reicht eine Facebook-Seite?", "answer": "Du brauchst einen Ort, zu dem die Anzeige führt und an dem der Interessent entscheiden kann. Am besten eine dafür gebaute Landingpage oder eine gut strukturierte Website, denn dort steuerst du das Erlebnis und kannst messen. Fehlt eine geeignete Seite, kommen Website und Werbung bei uns aus einer Hand.", "topic": "Werbeanzeigen", "alt_questions": []}}'::jsonb),
  ('web-hirdeteskezeles-8', 'Garantáljátok, hogy megnő az ügyfélszám?', 'Konkrét ügyfélszámot vagy bevételt tisztességesen senki nem garantálhat — aki mégis ilyet ígér, ott legyél óvatos. Amit garantálunk: szakszerű beállítás, mérésen alapuló folyamatos optimalizálás, átlátható riportálás és őszinte kommunikáció.', '{"en": {"question": "Do you guarantee more clients?", "answer": "No one can honestly guarantee a specific number of clients or a revenue figure — if someone promises that, be careful. What we do guarantee: professional setup, continuous optimisation based on measurement, transparent reporting and honest communication.", "topic": "Ads management", "alt_questions": []}, "de": {"question": "Garantiert ihr mehr Kunden?", "answer": "Eine konkrete Kundenzahl oder einen Umsatz kann seriös niemand garantieren — wer das verspricht, sollte dich misstrauisch machen. Was wir garantieren: fachgerechte Einrichtung, laufende Optimierung auf Basis von Messwerten, transparentes Reporting und ehrliche Kommunikation.", "topic": "Werbeanzeigen", "alt_questions": []}}'::jsonb),
  ('web-hirdeteskezeles-9', 'Ki írja a hirdetésszövegeket és készíti a kreatívokat?', 'A szövegezés és a kampányok felépítése a mi dolgunk — ez benne van a szolgáltatásban. A vizuális kreatívoknál a legjobb, ha a tényleges munkádról, termékedről kapunk anyagot, mert a hiteles, valódi kép sokszor jobban teljesít, mint a steril stockfotó. Egy jó telefonos felvétel a kész munkádról gyakran aranyat ér.', '{"en": {"question": "Who writes the ad copy and makes the creative?", "answer": "Copywriting and campaign structure are our job — they''re part of the service. For visual creative it''s best if we get material from your actual work or products, because an authentic, real photo often outperforms a sterile stock image. A good phone shot of finished work is frequently worth its weight in gold.", "topic": "Ads management", "alt_questions": []}, "de": {"question": "Wer schreibt die Anzeigentexte und erstellt die Kreation?", "answer": "Texte und Kampagnenaufbau sind unsere Aufgabe — sie sind Teil der Leistung. Für visuelle Kreation ist es am besten, wenn wir Material von deiner tatsächlichen Arbeit oder deinen Produkten bekommen, denn ein echtes, authentisches Bild schlägt oft das sterile Stockfoto. Eine gute Handyaufnahme fertiger Arbeit ist oft Gold wert.", "topic": "Werbeanzeigen", "alt_questions": []}}'::jsonb),
  ('web-hirdeteskezeles-10', 'Mi a különbség a fizetett hirdetés és a SEO között?', 'A kettő nem egymás helyettesítője, hanem kiegészítője. A hirdetés azonnal hoz forgalmat: bekapcsolod, jönnek az érdeklődők — de amint elzárod a csapot, elapad. A SEO lassabban épül, hónapok munkája, viszont utána tartósan, hirdetési költség nélkül hozza az ügyfeleket. A kettő együtt a legerősebb.', '{"en": {"question": "What''s the difference between paid advertising and SEO?", "answer": "They don''t replace each other, they complement each other. Advertising brings traffic immediately: switch it on and enquiries arrive — but the moment you close the tap it dries up. SEO builds more slowly, taking months of work, but afterwards it brings clients steadily without ad spend. Together they''re strongest.", "topic": "Ads management", "alt_questions": []}, "de": {"question": "Was ist der Unterschied zwischen bezahlter Werbung und SEO?", "answer": "Sie ersetzen einander nicht, sie ergänzen sich. Werbung bringt sofort Traffic: einschalten, Anfragen kommen — aber sobald du den Hahn zudrehst, versiegt es. SEO baut sich langsamer auf, kostet Monate Arbeit, bringt danach aber dauerhaft Kunden ohne Werbebudget. Zusammen sind beide am stärksten.", "topic": "Werbeanzeigen", "alt_questions": []}}'::jsonb),
  ('web-impact-program-1', 'Tényleg ingyenes?', 'Igen, teljesen. A kiválasztott szervezetek semmit nem fizetnek. Nincsenek rejtett díjak, licencköltségek vagy kötelezettségek. A dizájnt, a fejlesztést és az élesítést mi álljuk.', '{"en": {"question": "Is it really free?", "answer": "Yes, entirely. Selected organisations pay nothing. There are no hidden fees, licence costs or obligations. We cover the design, the development and the launch.", "topic": "Impact Program", "alt_questions": ["Is the Impact Program really free?", "Does the Impact Program cost anything?"]}, "de": {"question": "Ist es wirklich kostenlos?", "answer": "Ja, vollständig. Ausgewählte Organisationen zahlen nichts. Es gibt keine versteckten Gebühren, Lizenzkosten oder Verpflichtungen. Design, Entwicklung und Launch übernehmen wir.", "topic": "Impact-Programm", "alt_questions": ["Ist das Impact-Programm wirklich kostenlos?", "Kostet das Impact-Programm etwas?"]}}'::jsonb),
  ('web-impact-program-2', 'Miért csináljátok ezt?', 'Mert első kézből láttuk, mennyire fontosak a rehabilitációval, mentális egészséggel és gyermekvédelemmel foglalkozó szervezetek. Megvan a szakértelmünk, hogy segítsünk, ezért segítünk.', '{"en": {"question": "Why do you do this?", "answer": "Because we''ve seen first hand how vital organisations working in rehabilitation, mental health and child protection are. We have the expertise to help, so we help.", "topic": "Impact Program", "alt_questions": []}, "de": {"question": "Warum macht ihr das?", "answer": "Weil wir aus erster Hand gesehen haben, wie wichtig Organisationen in Rehabilitation, psychischer Gesundheit und Kinderschutz sind. Wir haben das Können zu helfen — also helfen wir.", "topic": "Impact-Programm", "alt_questions": []}}'::jsonb),
  ('web-impact-program-3', 'Ki jelentkezhet?', 'Olyan nonprofit szervezetek, amelyek valódi, mérhető társadalmi hatást hoznak létre, és nyitottak az együttműködésre. Előnyt élveznek a felépüléssel, mentális egészséggel és gyermekvédelemmel foglalkozó szervezetek.', '{"en": {"question": "Who can apply?", "answer": "Nonprofit organisations that create real, measurable social impact and are open to working together. Priority goes to organisations working in recovery, mental health and child protection.", "topic": "Impact Program", "alt_questions": []}, "de": {"question": "Wer kann sich bewerben?", "answer": "Gemeinnützige Organisationen, die echte, messbare gesellschaftliche Wirkung erzielen und offen für Zusammenarbeit sind. Vorrang haben Organisationen in Genesung, psychischer Gesundheit und Kinderschutz.", "topic": "Impact-Programm", "alt_questions": []}}'::jsonb),
  ('web-impact-program-4', 'Hány szervezetet választotok ki?', 'Évente csak néhányat. Szándékosan tartjuk kicsiben a létszámot, hogy minden szervezet teljes figyelmet és a legmagasabb színvonalú weboldalt kapja.', '{"en": {"question": "How many organisations do you select?", "answer": "Only a handful each year. We deliberately keep the number small so every organisation gets our full attention and the highest quality website.", "topic": "Impact Program", "alt_questions": []}, "de": {"question": "Wie viele Organisationen wählt ihr aus?", "answer": "Nur eine Handvoll pro Jahr. Wir halten die Zahl bewusst klein, damit jede Organisation volle Aufmerksamkeit und die bestmögliche Website bekommt.", "topic": "Impact-Programm", "alt_questions": []}}'::jsonb),
  ('web-impact-program-5', 'Karbantartjátok a weboldalt?', 'Minden szervezet kap kezdeti technikai támogatást az élesítés után. A hosszabb távú igényeket az egyeztetésen közösen beszéljük át.', '{"en": {"question": "Do you maintain the website?", "answer": "Every organisation gets initial technical support after launch. Longer-term needs we discuss together during the conversation.", "topic": "Impact Program", "alt_questions": []}, "de": {"question": "Wartet ihr die Website?", "answer": "Jede Organisation erhält nach dem Launch anfänglichen technischen Support. Längerfristigen Bedarf besprechen wir gemeinsam im Gespräch.", "topic": "Impact-Programm", "alt_questions": []}}'::jsonb),
  ('web-impact-program-6', 'Meglévő weboldalt is újraterveztek?', 'Természetesen. Akár a nulláról indultok, akár egy elavult oldalt váltanátok le, modern, professzionális jelenlétet építünk az alapoktól.', '{"en": {"question": "Do you also redesign existing websites?", "answer": "Of course. Whether you''re starting from scratch or replacing an outdated site, we build a modern, professional presence from the ground up.", "topic": "Impact Program", "alt_questions": []}, "de": {"question": "Gestaltet ihr auch bestehende Websites neu?", "answer": "Selbstverständlich. Ob ihr bei null anfangt oder eine veraltete Seite ablösen wollt — wir bauen einen modernen, professionellen Auftritt von Grund auf.", "topic": "Impact-Programm", "alt_questions": []}}'::jsonb),
  ('web-keresooptimalizalas-1', 'Mennyi idő alatt látszik eredmény?', 'A technikai javítások hatása néhány héten belül megjelenhet, mert a Google újra bejárja az oldalt. A tartalomból származó elmozdulás jellemzően a harmadik-negyedik hónap környékén válik mérhetővé. Aki ennél gyorsabbat ígér, az vagy hirdetést árul SEO néven, vagy olyan módszert használ, aminek később ára lesz.', '{"en": {"question": "How long before results show?", "answer": "Technical fixes can show within a few weeks, because Google re-crawls the site. Movement from content usually becomes measurable around the third or fourth month. Anyone promising faster is either selling advertising under the name SEO, or using a method that has a price later.", "topic": "SEO", "alt_questions": []}, "de": {"question": "Wann zeigen sich Ergebnisse?", "answer": "Technische Korrekturen können sich innerhalb weniger Wochen zeigen, weil Google die Seite neu crawlt. Bewegung aus Inhalten wird meist im dritten bis vierten Monat messbar. Wer Schnelleres verspricht, verkauft entweder Werbung unter dem Namen SEO oder nutzt eine Methode, die später einen Preis hat.", "topic": "Suchmaschinenoptimierung", "alt_questions": []}}'::jsonb),
  ('web-keresooptimalizalas-2', 'Garantáltok első helyet a Google-ben?', 'Nem, és senki más sem tud. Az első helyet a Google rangsorolása dönti el, ami folyamatosan változik, és amire senkinek nincs ráhatása. Amit garantálni tudunk, az a munka: mit mérünk, mit javítunk, mit írunk meg, és hogy erről havonta érthető riportot kapsz.', '{"en": {"question": "Do you guarantee first place on Google?", "answer": "No, and nobody can. First place is decided by Google''s ranking, which changes constantly and which nobody controls. What we can guarantee is the work: what we measure, what we fix, what we write, and a readable report on it every month.", "topic": "SEO", "alt_questions": []}, "de": {"question": "Garantieren Sie Platz eins bei Google?", "answer": "Nein, und niemand kann das. Platz eins entscheidet Googles Ranking, das sich ständig ändert und das niemand steuert. Garantieren können wir die Arbeit: was wir messen, was wir korrigieren, was wir schreiben — und einen verständlichen Report jeden Monat.", "topic": "Suchmaschinenoptimierung", "alt_questions": []}}'::jsonb),
  ('web-keresooptimalizalas-3', 'Mennyibe kerül a keresőoptimalizálás?', 'Attól függ, milyen állapotban van az oldal, és mekkora a mező, amiben versenyzel. Egy helyi szolgáltatónál lényegesen kevesebb munka kell, mint egy országos webáruháznál. A díjmentes feltárás után kapsz egy konkrét ajánlatot, benne azzal, hogy pontosan mit csinálunk az első négy hónapban.', '{"en": {"question": "What does SEO cost?", "answer": "It depends on the state of the site and the size of the field you compete in. A local service business needs considerably less work than a national online store. After the free discovery you get a concrete quote, including exactly what we will do in the first four months.", "topic": "SEO", "alt_questions": []}, "de": {"question": "Was kostet SEO?", "answer": "Das hängt vom Zustand der Seite ab und davon, wie groß das Feld ist, in dem Sie antreten. Ein lokaler Dienstleister braucht deutlich weniger Arbeit als ein landesweiter Onlineshop. Nach der kostenlosen Analyse erhalten Sie ein konkretes Angebot samt genauem Plan für die ersten vier Monate.", "topic": "Suchmaschinenoptimierung", "alt_questions": []}}'::jsonb),
  ('web-keresooptimalizalas-4', 'Kell hozzá új weboldal?', 'Nem feltétlenül. A legtöbb meglévő oldalon van elég mozgástér ahhoz, hogy érdemes legyen elkezdeni. Ha a feltárás során kiderül, hogy az oldal szerkezete vagy sebessége miatt a munka nagy része kárba veszne, ezt megmondjuk, és inkább a weboldalt hozzuk rendbe először.', '{"en": {"question": "Do I need a new website for it?", "answer": "Not necessarily. Most existing sites have enough room to make starting worthwhile. If discovery shows that the site''s structure or speed would waste most of the work, we say so, and fix the website first instead.", "topic": "SEO", "alt_questions": []}, "de": {"question": "Brauche ich dafür eine neue Website?", "answer": "Nicht unbedingt. Die meisten bestehenden Seiten bieten genug Spielraum, dass sich der Start lohnt. Zeigt die Analyse, dass Struktur oder Geschwindigkeit den Großteil der Arbeit verpuffen ließen, sagen wir das und bringen zuerst die Website in Ordnung.", "topic": "Suchmaschinenoptimierung", "alt_questions": []}}'::jsonb),
  ('web-keresooptimalizalas-5', 'Mi a különbség a SEO és a Google Ads között?', 'A hirdetés azonnal hoz forgalmat, és akkor áll le, amikor kifogy a keret. A keresőoptimalizálás lassabban indul, de a megszerzett pozíció akkor is dolgozik, amikor nem költesz. A kettő nem egymás alternatívája: a Rapidkertnél párhuzamosan futottak, és külön-külön is termeltek.', '{"en": {"question": "What is the difference between SEO and Google Ads?", "answer": "Advertising brings traffic immediately and stops when the budget runs out. SEO starts more slowly, but a position you have earned keeps working when you are not spending. They are not alternatives: at Rapidkert both ran in parallel and each produced on its own.", "topic": "SEO", "alt_questions": []}, "de": {"question": "Was ist der Unterschied zwischen SEO und Google Ads?", "answer": "Werbung bringt sofort Traffic und endet, wenn das Budget aufgebraucht ist. SEO startet langsamer, aber eine erarbeitete Position arbeitet weiter, auch wenn Sie nichts ausgeben. Die beiden sind keine Alternativen: Bei Rapidkert liefen sie parallel und lieferten jeweils eigenständig.", "topic": "Suchmaschinenoptimierung", "alt_questions": []}}'::jsonb),
  ('web-keresooptimalizalas-6', 'Ha felmondom, elveszik minden?', 'Nem. Amit megírtunk és megjavítottunk, az az oldaladon marad, és tovább dolgozik. A pozíciók idővel romolhatnak, ha senki nem foglalkozik velük, de nem tűnnek el egyik napról a másikra, és semmit nem kapcsolunk le.', '{"en": {"question": "If I stop, do I lose everything?", "answer": "No. What we wrote and fixed stays on your site and keeps working. Positions can decay over time if nobody tends them, but they do not vanish overnight, and we switch nothing off.", "topic": "SEO", "alt_questions": []}, "de": {"question": "Wenn ich kündige, ist alles weg?", "answer": "Nein. Was wir geschrieben und korrigiert haben, bleibt auf Ihrer Seite und arbeitet weiter. Positionen können mit der Zeit nachlassen, wenn sich niemand kümmert, aber sie verschwinden nicht über Nacht — und wir schalten nichts ab.", "topic": "Suchmaschinenoptimierung", "alt_questions": []}}'::jsonb),
  ('web-kkv-1', 'Mennyi idő alatt készül el egy weboldal?', 'A pontos határidőt a projekt terjedelme és a szükséges anyagok rendelkezésre állása alapján, az egyeztetés során rögzítjük.', '{"en": {"question": "How long does a website take?", "answer": "We set the exact deadline during our consultation, based on the scope of the project and when the materials we need are available.", "topic": "Website", "alt_questions": []}, "de": {"question": "Wie lange dauert eine Website?", "answer": "Den genauen Termin legen wir im Abstimmungsgespräch fest — je nach Umfang des Projekts und danach, wann die nötigen Materialien vorliegen.", "topic": "Website", "alt_questions": []}}'::jsonb),
  ('web-kkv-2', 'Miért előnyös a havidíjas konstrukció a nagy egyszeri költség helyett?', 'Így nem kell egyszerre több százezer forintos beruházást vállalnod, hanem kiszámítható, alacsonyabb havi költséggel indíthatod el az online jelenléted. A havidíj emellett a folyamatos karbantartást, tárhelyet, frissítéseket és supportot is tartalmazza, így nem érnek váratlan extra költségek.', '{"en": {"question": "Why is a monthly fee better than a large one-off cost?", "answer": "You don''t have to commit to a four-figure investment in one go; you can start your online presence with a predictable, lower monthly cost. The fee also covers ongoing maintenance, hosting, updates and support, so no unexpected extra costs turn up.", "topic": "Website", "alt_questions": ["Why is the monthly plan better than large one-off costs?"]}, "de": {"question": "Warum ist die Monatsgebühr besser als hohe Einmalkosten?", "answer": "Du musst keine vierstellige Investition auf einmal stemmen, sondern startest deinen Online-Auftritt mit planbaren, niedrigeren Monatskosten. Die Gebühr deckt zudem laufende Wartung, Hosting, Updates und Support ab — unerwartete Zusatzkosten gibt es nicht.", "topic": "Website", "alt_questions": ["Warum ist das Monatsmodell besser als hohe Einmalkosten?"]}}'::jsonb),
  ('web-kkv-3', 'Mennyire lesz testreszabott a weboldalam?', 'A weboldalad a te márkádhoz, arculatodhoz és céljaidhoz igazodva készül, nem egy sablonból dolgozunk kreatív keretek nélkül. A dizájn, a szövegezés és a funkciók is a te vállalkozásod igényei alapján kerülnek kialakításra.', '{"en": {"question": "How custom will my website be?", "answer": "Your website is built around your brand, your visual identity and your goals — we don''t work from a template with no creative room. The design, the copy and the features all follow the needs of your business.", "topic": "Website", "alt_questions": []}, "de": {"question": "Wie individuell wird meine Website?", "answer": "Deine Website entsteht rund um deine Marke, dein Erscheinungsbild und deine Ziele — wir arbeiten nicht ohne kreativen Spielraum aus einer Vorlage. Design, Texte und Funktionen richten sich nach den Anforderungen deines Unternehmens.", "topic": "Website", "alt_questions": []}}'::jsonb),
  ('web-kkv-4', 'Később bővíthető vagy fejleszthető a rendszer?', 'Igen, a weboldal moduláris felépítésű, így új oldalakkal, funkciókkal vagy akár webshoppal is bővíthető, ahogy a vállalkozásod növekszik. Nem kell mindent az elején eldöntened, a rendszer veled együtt fejlődik.', '{"en": {"question": "Can the system be extended later?", "answer": "Yes. The website is modular, so new pages, features or even an online shop can be added as your business grows. You don''t have to decide everything at the start — the system grows with you.", "topic": "Website", "alt_questions": []}, "de": {"question": "Lässt sich das System später erweitern?", "answer": "Ja. Die Website ist modular aufgebaut, sodass neue Seiten, Funktionen oder sogar ein Onlineshop ergänzt werden können, während dein Unternehmen wächst. Du musst nicht alles am Anfang entscheiden — das System wächst mit.", "topic": "Website", "alt_questions": []}}'::jsonb),
  ('web-kkv-5', 'Mobiltelefonon és tableten is megfelelően működik majd az oldal?', 'Igen, minden weboldal reszponzív kialakítású, vagyis automatikusan alkalmazkodik mobiltelefonhoz, tablethez és asztali géphez egyaránt. Ezt élesítés előtt minden eszköztípuson leteszteljük.', '{"en": {"question": "Will the site work properly on phones and tablets?", "answer": "Yes. Every website is responsive, so it adapts automatically to phones, tablets and desktops. We test this on every device type before launch.", "topic": "Website", "alt_questions": []}, "de": {"question": "Funktioniert die Seite auch auf Handy und Tablet?", "answer": "Ja. Jede Website ist responsiv und passt sich automatisch an Handy, Tablet und Desktop an. Das testen wir vor dem Go-live auf jedem Gerätetyp.", "topic": "Website", "alt_questions": []}}'::jsonb),
  ('web-kkv-6', 'Segítetek a Google és Meta hirdetések kezelésében is?', 'Igen, kérésre a Google és Meta (Facebook/Instagram) hirdetéseid beállításában és kezelésében is tudunk segíteni, a célzástól a kampányok folyamatos optimalizálásáig. Így a weboldalad mellett a hozzá vezető forgalom is szakértő kezekben van.', '{"en": {"question": "Do you also manage Google and Meta ads?", "answer": "Yes. On request we can help set up and run your Google and Meta (Facebook/Instagram) advertising, from targeting to continuous campaign optimisation. That way the traffic reaching your site is in expert hands too.", "topic": "Website", "alt_questions": []}, "de": {"question": "Betreut ihr auch Google- und Meta-Werbung?", "answer": "Ja. Auf Wunsch helfen wir bei Einrichtung und Betreuung deiner Google- und Meta-Werbung (Facebook/Instagram) — vom Targeting bis zur laufenden Kampagnenoptimierung. So ist neben der Website auch der Traffic dorthin in erfahrenen Händen.", "topic": "Website", "alt_questions": []}}'::jsonb),
  ('web-kkv-7', 'Kapok segítséget abban, hogy megértsem, mi hogyan működik?', 'Természetesen, nem hagyunk magadra az átadás után. Érthetően elmagyarázzuk, hogyan működik az oldalad, és a legfontosabb fogalmakat is végigvesszük, hogy magabiztosan tudj döntéseket hozni.', '{"en": {"question": "Will you help me understand how it all works?", "answer": "Of course — we do not leave you on your own after handover. We explain how your site works in plain terms and go through the concepts that matter, so you can make decisions with confidence.", "topic": "Website", "alt_questions": ["Do I get help understanding how the website works and the basics of online marketing?"]}, "de": {"question": "Helfen Sie mir zu verstehen, wie alles funktioniert?", "answer": "Selbstverständlich — nach der Übergabe lassen wir Sie nicht allein. Wir erklären verständlich, wie Ihre Seite funktioniert, und gehen die wichtigsten Begriffe durch, damit Sie sicher entscheiden können.", "topic": "Website", "alt_questions": ["Bekomme ich Hilfe dabei, die Website und die Grundlagen des Online-Marketings zu verstehen?"]}}'::jsonb),
  ('web-kkv-8', 'Hogyan követhető a weboldal és a hirdetések teljesítménye?', 'A weboldalhoz és a hirdetésekhez is átlátható statisztikákat biztosítunk, amelyekből látod a látogatottságot, a legfontosabb mutatókat és a kampányok eredményességét. Igény esetén rendszeres, közérthető riportokban is összefoglaljuk a teljesítményt.', '{"en": {"question": "How is the performance of the site and the ads tracked?", "answer": "We provide clear statistics for both the website and the ads, showing traffic, the key metrics and campaign results. On request we also summarise performance in regular, plain-language reports.", "topic": "Website", "alt_questions": []}, "de": {"question": "Wie wird die Leistung von Website und Werbung gemessen?", "answer": "Für Website und Werbung liefern wir verständliche Statistiken mit Besucherzahlen, den wichtigsten Kennzahlen und Kampagnenergebnissen. Auf Wunsch fassen wir die Leistung zusätzlich in regelmäßigen, klar formulierten Reports zusammen.", "topic": "Website", "alt_questions": []}}'::jsonb),
  ('web-kkv-9', 'Kié a weboldal és a domain?', 'A domain és minden tartalom a tiéd. Az oldalt mi üzemeltetjük, amíg él az előfizetés; ha felmondod, a domaint és a tartalmaidat természetesen átadjuk.', '{"en": {"question": "Who owns the website and the domain?", "answer": "The domain and all content are yours. We operate the site while the subscription runs; if you cancel, we of course hand over the domain and your content.", "topic": "Website", "alt_questions": []}, "de": {"question": "Wem gehören Website und Domain?", "answer": "Domain und sämtliche Inhalte gehören dir. Wir betreiben die Seite, solange das Abo läuft; bei Kündigung übergeben wir Domain und Inhalte selbstverständlich.", "topic": "Website", "alt_questions": []}}'::jsonb),
  ('web-kkv-10', 'Van hűségidő vagy kötbér?', 'Nincs. A szerződés havonta mondható fel, rejtett költségek nélkül. Addig maradsz, amíg elégedett vagy a szolgáltatással.', '{"en": {"question": "Is there a minimum term or a penalty?", "answer": "No. The contract can be cancelled monthly, with no hidden costs. You stay as long as you''re happy with the service.", "topic": "Website", "alt_questions": []}, "de": {"question": "Gibt es Mindestlaufzeit oder Vertragsstrafe?", "answer": "Nein. Der Vertrag ist monatlich kündbar, ohne versteckte Kosten. Du bleibst so lange, wie du zufrieden bist.", "topic": "Website", "alt_questions": []}}'::jsonb),
  ('web-kkv-11', 'Mit kell nekem biztosítanom a kezdéshez?', 'Elég néhány alapinformáció a vállalkozásodról, valamint szövegek és képek, ha vannak. Ha nincsenek, a megfogalmazásban és a képek kiválasztásában is segítünk, hogy ne ezen múljon az indulás.', '{"en": {"question": "What do I need to provide to get started?", "answer": "A few basics about your business, plus copy and images if you have them. If you don''t, we help with the wording and with choosing images, so that''s never what holds the launch up.", "topic": "Website", "alt_questions": []}, "de": {"question": "Was muss ich für den Start bereitstellen?", "answer": "Ein paar Grundinformationen über dein Unternehmen sowie Texte und Bilder, falls vorhanden. Wenn nicht, helfen wir bei Formulierung und Bildauswahl — daran soll der Start nicht scheitern.", "topic": "Website", "alt_questions": []}}'::jsonb),
  ('web-kkv-12', 'Mi van, ha már van weboldalam?', 'Meglévő oldalt is átveszünk. Átnézzük, mi menthető belőle, és vagy megújítjuk, vagy újat építünk helyette; a tartalmaid és a domained természetesen megmaradnak.', '{"en": {"question": "What if I already have a website?", "answer": "We take over existing sites too. We review what''s worth keeping and either refresh it or build a new one in its place; your content and your domain stay with you.", "topic": "Website", "alt_questions": []}, "de": {"question": "Was, wenn ich schon eine Website habe?", "answer": "Bestehende Seiten übernehmen wir ebenfalls. Wir prüfen, was erhaltenswert ist, und erneuern sie entweder oder bauen eine neue; Inhalte und Domain bleiben selbstverständlich bei dir.", "topic": "Website", "alt_questions": []}}'::jsonb),
  ('web-nagyvallalat-1', 'Milyen SLA-t és rendelkezésre állást vállaltok?', 'Az üzleti kritikusságtól függően definiálunk SLA-t: garantált rendelkezésre állást (jellemzően 99,9%), definiált reakció- és megoldási időket, valamint eszkalációs folyamatot. A pontos szinteket a szerződésben rögzítjük, és riportokban követjük.', '{"en": {"question": "What SLA and uptime do you commit to?", "answer": "We define the SLA according to business criticality: guaranteed uptime (typically 99.9%), defined response and resolution times, and an escalation process. Exact levels are set in the contract and tracked in reports.", "topic": "Enterprise development", "alt_questions": []}, "de": {"question": "Welches SLA und welche Verfügbarkeit sagt ihr zu?", "answer": "Wir definieren das SLA nach Geschäftskritikalität: garantierte Verfügbarkeit (typisch 99,9 %), definierte Reaktions- und Lösungszeiten sowie einen Eskalationsprozess. Die genauen Stufen halten wir im Vertrag fest und verfolgen sie in Reports.", "topic": "Entwicklung für Unternehmen", "alt_questions": []}}'::jsonb),
  ('web-nagyvallalat-2', 'Hogyan illeszkedtek a meglévő rendszereinkhez és folyamatainkhoz?', 'A fejlesztést a meglévő infrastruktúrátokra tervezzük: ERP, CRM, SSO, fizetési és logisztikai rendszerek integrációjával. Igazodunk a belső folyamataitokhoz, a biztonsági előírásaitokhoz és a fejlesztési sztenderdjeitekhez, legyen szó cloud vagy on-premise környezetről.', '{"en": {"question": "How do you fit into our existing systems and processes?", "answer": "We design development around your existing infrastructure, integrating ERP, CRM, SSO, payment and logistics systems. We follow your internal processes, security requirements and development standards, whether the environment is cloud or on-premise.", "topic": "Enterprise development", "alt_questions": []}, "de": {"question": "Wie fügt ihr euch in unsere bestehenden Systeme und Prozesse ein?", "answer": "Wir planen die Entwicklung auf eurer bestehenden Infrastruktur, mit Integration von ERP, CRM, SSO, Zahlungs- und Logistiksystemen. Wir richten uns nach euren internen Prozessen, Sicherheitsvorgaben und Entwicklungsstandards — ob Cloud oder On-Premise.", "topic": "Entwicklung für Unternehmen", "alt_questions": []}}'::jsonb),
  ('web-nagyvallalat-3', 'Hogyan kezelitek az adatbiztonságot és a GDPR-megfelelőséget?', 'A biztonság a tervezés része, nem utólagos réteg: hozzáférés-kezelés, titkosítás, auditnaplózás és rendszeres biztonsági tesztek. GDPR-megfelelő adatkezelést, adatfeldolgozói szerződést és igény esetén penetrációs teszteket, valamint a belső compliance-előírásaitokhoz igazodó folyamatot biztosítunk.', '{"en": {"question": "How do you handle data security and GDPR compliance?", "answer": "Security is part of the design, not a layer added afterwards: access management, encryption, audit logging and regular security testing. We provide GDPR-compliant data handling, a data processing agreement, penetration tests on request, and a process aligned with your internal compliance requirements.", "topic": "Enterprise development", "alt_questions": []}, "de": {"question": "Wie geht ihr mit Datensicherheit und DSGVO-Konformität um?", "answer": "Sicherheit ist Teil der Konzeption, keine nachträgliche Schicht: Zugriffsverwaltung, Verschlüsselung, Audit-Logging und regelmäßige Sicherheitstests. Wir bieten DSGVO-konforme Datenverarbeitung, einen Auftragsverarbeitungsvertrag, auf Wunsch Penetrationstests und einen Prozess, der euren internen Compliance-Vorgaben folgt.", "topic": "Entwicklung für Unternehmen", "alt_questions": []}}'::jsonb),
  ('web-nagyvallalat-4', 'Skálázható a megoldás több piacra és nagy terhelésre?', 'Igen. A rendszereket eleve skálázható architektúrára tervezzük: több nyelv és piac, terheléshez igazodó infrastruktúra, cache és CDN, valamint moduláris felépítés. Ahogy nőtök, a rendszer és a hozzá rendelt csapatkapacitás is együtt skálázódik.', '{"en": {"question": "Does the solution scale to multiple markets and heavy load?", "answer": "Yes. We design the systems on a scalable architecture from the start: multiple languages and markets, load-adaptive infrastructure, caching and CDN, and a modular build. As you grow, both the system and the assigned team capacity scale with you.", "topic": "Enterprise development", "alt_questions": []}, "de": {"question": "Skaliert die Lösung auf mehrere Märkte und hohe Last?", "answer": "Ja. Wir entwerfen die Systeme von Anfang an auf skalierbarer Architektur: mehrere Sprachen und Märkte, lastabhängige Infrastruktur, Caching und CDN sowie modularer Aufbau. Wenn ihr wachst, skalieren System und zugeordnete Teamkapazität mit.", "topic": "Entwicklung für Unternehmen", "alt_questions": []}}'::jsonb),
  ('web-nagyvallalat-5', 'Hogyan áll fel és hogyan skálázódik a dedikált csapat?', 'A projekthez dedikált csapatot rendelünk — fejlesztők, dizájner és egy állandó projektvezető, aki a ti oldalatokon egy kapcsolattartó. A kapacitást a terheléshez igazítjuk: fel- és leskálázzuk a csapatot a roadmap és a sprintek igényei szerint.', '{"en": {"question": "How is the dedicated team assembled and scaled?", "answer": "We assign a dedicated team to the project — developers, a designer and a permanent project lead who is your single point of contact. Capacity follows the workload: we scale the team up and down according to the roadmap and sprint needs.", "topic": "Enterprise development", "alt_questions": []}, "de": {"question": "Wie wird das dedizierte Team aufgestellt und skaliert?", "answer": "Wir stellen dem Projekt ein dediziertes Team zur Seite — Entwickler, Designer und eine feste Projektleitung als eure einzige Ansprechperson. Die Kapazität folgt der Auslastung: Wir skalieren das Team nach Roadmap und Sprintbedarf hoch und runter.", "topic": "Entwicklung für Unternehmen", "alt_questions": []}}'::jsonb),
  ('web-nagyvallalat-6', 'Kié a forráskód és a szellemi tulajdon?', 'A forráskód, a dokumentáció és minden szellemi termék a tiétek. A repókhoz és a környezetekhez teljes hozzáférést adunk, a folyamat átlátható, és bármikor átvehető akár a belső csapatotok által is — nincs vendor lock-in.', '{"en": {"question": "Who owns the source code and the intellectual property?", "answer": "The source code, documentation and all intellectual property are yours. We give full access to the repositories and environments, the process is transparent, and your internal team can take it over at any time — no vendor lock-in.", "topic": "Enterprise development", "alt_questions": []}, "de": {"question": "Wem gehören Quellcode und geistiges Eigentum?", "answer": "Quellcode, Dokumentation und sämtliches geistiges Eigentum gehören euch. Wir geben vollen Zugriff auf Repositories und Umgebungen, der Prozess ist transparent, und euer internes Team kann jederzeit übernehmen — kein Vendor-Lock-in.", "topic": "Entwicklung für Unternehmen", "alt_questions": []}}'::jsonb),
  ('web-nagyvallalat-7', 'Milyen technológiákkal dolgoztok?', 'Modern, jól támogatott stacket használunk (pl. React/Next.js, Node, TypeScript, felhő- és konténeralapú infrastruktúra), de mindig az adott feladathoz és a ti meglévő környezetetekhez választjuk a megfelelő eszközt. A cél a hosszú távon karbantartható, ipari sztenderdeket követő megoldás.', '{"en": {"question": "What technologies do you work with?", "answer": "We use a modern, well-supported stack (React/Next.js, Node, TypeScript, cloud and container-based infrastructure), but we always pick the right tool for the task and for your existing environment. The goal is a long-term maintainable solution that follows industry standards.", "topic": "Enterprise development", "alt_questions": []}, "de": {"question": "Mit welchen Technologien arbeitet ihr?", "answer": "Wir nutzen einen modernen, gut unterstützten Stack (z. B. React/Next.js, Node, TypeScript, Cloud- und containerbasierte Infrastruktur), wählen das Werkzeug aber immer passend zur Aufgabe und zu eurer bestehenden Umgebung. Ziel ist eine langfristig wartbare Lösung nach Industriestandards.", "topic": "Entwicklung für Unternehmen", "alt_questions": []}}'::jsonb),
  ('web-nagyvallalat-8', 'Átvesztek meglévő, más által fejlesztett rendszert?', 'Igen. Először technikai auditot végzünk: átnézzük a kódot, az architektúrát és a kockázatokat, majd javaslatot teszünk a stabilizálásra, továbbfejlesztésre vagy szükség esetén a fokozatos újraépítésre. Az átvételt kontrolláltan, a működés megszakítása nélkül végezzük.', '{"en": {"question": "Do you take over existing systems built by someone else?", "answer": "Yes. First we run a technical audit: we review the code, the architecture and the risks, then propose stabilisation, further development or, where needed, a gradual rebuild. The handover is controlled and doesn''t interrupt operations.", "topic": "Enterprise development", "alt_questions": []}, "de": {"question": "Übernehmt ihr bestehende, von anderen entwickelte Systeme?", "answer": "Ja. Zuerst führen wir ein technisches Audit durch: Wir prüfen Code, Architektur und Risiken und schlagen dann Stabilisierung, Weiterentwicklung oder — falls nötig — einen schrittweisen Neuaufbau vor. Die Übernahme erfolgt kontrolliert und ohne Betriebsunterbrechung.", "topic": "Entwicklung für Unternehmen", "alt_questions": []}}'::jsonb),
  ('web-nagyvallalat-9', 'Hogyan zajlik a riportálás és a projektkövetés?', 'Sprintekben dolgozunk, rendszeres demókkal és átlátható backloggal. Hozzáférést kaptok a projektkövető és a monitoring felületekhez, és rendszeres, vezetői szintre is érthető riportokban foglaljuk össze a haladást, a KPI-okat és a rendszer teljesítményét.', '{"en": {"question": "How does reporting and project tracking work?", "answer": "We work in sprints with regular demos and a transparent backlog. You get access to the project tracking and monitoring dashboards, and we summarise progress, KPIs and system performance in regular reports that also read at board level.", "topic": "Enterprise development", "alt_questions": []}, "de": {"question": "Wie laufen Reporting und Projektverfolgung?", "answer": "Wir arbeiten in Sprints mit regelmäßigen Demos und transparentem Backlog. Ihr erhaltet Zugriff auf Projekt-Tracking und Monitoring, und wir fassen Fortschritt, KPIs und Systemleistung in regelmäßigen Reports zusammen, die auch auf Führungsebene verständlich sind.", "topic": "Entwicklung für Unternehmen", "alt_questions": []}}'::jsonb),
  ('web-nagyvallalat-10', 'Milyen szerződéses és elszámolási modellben dolgoztok?', 'A projekt jellegétől függően dolgozhatunk fix áras keretben, dedikált csapat (time & material) modellben vagy folyamatos üzemeltetési retainerben. A beszerzési, jogi és compliance-folyamataitokhoz igazodunk, és minden feltételt keretszerződésben rögzítünk.', '{"en": {"question": "What contract and billing models do you work with?", "answer": "Depending on the nature of the project we can work to a fixed-price scope, a dedicated team (time & material) model or an ongoing operations retainer. We adapt to your procurement, legal and compliance processes and set all terms in a framework agreement.", "topic": "Enterprise development", "alt_questions": []}, "de": {"question": "In welchen Vertrags- und Abrechnungsmodellen arbeitet ihr?", "answer": "Je nach Projektcharakter arbeiten wir im Festpreisrahmen, im Modell des dedizierten Teams (Time & Material) oder im laufenden Betriebs-Retainer. Wir passen uns euren Beschaffungs-, Rechts- und Compliance-Prozessen an und halten alle Bedingungen in einem Rahmenvertrag fest.", "topic": "Entwicklung für Unternehmen", "alt_questions": []}}'::jsonb),
  ('web-webshop-keszites-1', 'Mennyibe kerül egy webshop készítés?', 'Attól függ, hány terméked van, hány variánssal, és mihez kell kapcsolódnia. Egy néhány száz termékes bolt havidíjas konstrukcióban is mehet, egy több ezer tételes, ERP-hez kötött rendszer projektalapon árazódik. A díjmentes konzultáció után kapsz konkrét számot.', '{"en": {"question": "What does an online store cost?", "answer": "It depends on how many products you have, with how many variants, and what it has to connect to. A few-hundred-product store can run on the monthly fee; a several-thousand-item system tied to an ERP is priced per project. You get a concrete figure after the free consultation.", "topic": "Online shop", "alt_questions": []}, "de": {"question": "Was kostet ein Onlineshop?", "answer": "Das hängt davon ab, wie viele Produkte Sie haben, mit wie vielen Varianten und woran der Shop angebunden sein muss. Ein Shop mit einigen hundert Produkten läuft auch im Monatsmodell; ein System mit mehreren tausend Artikeln und ERP-Anbindung wird pro Projekt kalkuliert.", "topic": "Onlineshop", "alt_questions": []}}'::jsonb),
  ('web-webshop-keszites-2', 'Mennyi idő alatt készül el?', 'Egy tipikus bolt hat-tíz hét a szerződéstől az élesítésig. A leghosszabb szakasz nem a fejlesztés, hanem a terméktörzs: a fotók, a leírások és a variánsok rendbetétele. Ha ez megvan, gyorsabban végzünk; ha nincs, ebben is segítünk.', '{"en": {"question": "How long does it take?", "answer": "A typical store is six to ten weeks from signature to launch. The longest stage is not the engineering but the product data: the photography, the descriptions and the variants. If that is ready we finish sooner; if it is not, we help with it.", "topic": "Online shop", "alt_questions": []}, "de": {"question": "Wie lange dauert es?", "answer": "Ein typischer Shop dauert sechs bis zehn Wochen von der Unterschrift bis zum Launch. Die längste Phase ist nicht die Entwicklung, sondern die Produktdaten: Fotos, Beschreibungen und Varianten. Liegen die vor, sind wir schneller fertig; wenn nicht, helfen wir dabei.", "topic": "Onlineshop", "alt_questions": []}}'::jsonb),
  ('web-webshop-keszites-3', 'Át tudtok venni egy meglévő webáruházat?', 'Igen. Először átnézzük, mi menthető belőle — a terméktörzs és a rendelési előzmény szinte mindig átvihető, a sablon és a bővítmények ritkán. Ha a meglévő rendszer működik és csak a láthatóság hiányzik, azt is megmondjuk, mielőtt bármit újraépítenénk.', '{"en": {"question": "Can you take over an existing store?", "answer": "Yes. First we look at what can be saved — product data and order history almost always migrate, the template and the plugins rarely do. If the existing system works and only visibility is missing, we say so before rebuilding anything.", "topic": "Online shop", "alt_questions": []}, "de": {"question": "Können Sie einen bestehenden Shop übernehmen?", "answer": "Ja. Zuerst prüfen wir, was zu retten ist — Produktdaten und Bestellhistorie lassen sich fast immer migrieren, Vorlage und Plugins selten. Wenn das bestehende System funktioniert und nur die Sichtbarkeit fehlt, sagen wir das, bevor wir etwas neu bauen.", "topic": "Onlineshop", "alt_questions": []}}'::jsonb),
  ('web-webshop-keszites-4', 'Kapok hozzá adminfelületet?', 'Igen, és arra a néhány dologra szabjuk, amit ténylegesen csinálni fogsz: termék felvitele, ár- és készletmódosítás, rendeléskezelés, kuponok. Nem egy húsz menüpontos panel, amiből hármat használsz.', '{"en": {"question": "Do I get an admin interface?", "answer": "Yes, and it is cut down to the few things you will actually do: adding products, changing price and stock, handling orders, coupons. Not a twenty-item panel of which you use three.", "topic": "Online shop", "alt_questions": []}, "de": {"question": "Bekomme ich ein Admin-Interface?", "answer": "Ja, und es ist auf die wenigen Dinge zugeschnitten, die Sie wirklich tun: Produkte anlegen, Preis und Bestand ändern, Bestellungen bearbeiten, Gutscheine. Kein Panel mit zwanzig Menüpunkten, von denen Sie drei nutzen.", "topic": "Onlineshop", "alt_questions": []}}'::jsonb),
  ('web-webshop-keszites-5', 'Ki felel a jogi megfelelésért?', 'A kötelező tartalmakat — ÁSZF, elállási tájékoztató, adatkezelés, cookie-kezelés — beépítjük, és megmondjuk, mi hiányzik. A szövegek tartalmi helyességéért viszont jogász felel, nem mi; ha nincs, szólunk időben, hogy legyen.', '{"en": {"question": "Who is responsible for legal compliance?", "answer": "We build in the required material — terms, right of withdrawal, privacy, cookie handling — and tell you what is missing. The substance of those texts is a lawyer''s responsibility, not ours; if you do not have one, we say so in time.", "topic": "Online shop", "alt_questions": []}, "de": {"question": "Wer ist für die rechtliche Konformität verantwortlich?", "answer": "Die Pflichtinhalte — AGB, Widerrufsbelehrung, Datenschutz, Cookie-Verwaltung — bauen wir ein und sagen Ihnen, was fehlt. Für die inhaltliche Richtigkeit dieser Texte haftet eine Anwältin, nicht wir; falls Sie keine haben, sagen wir rechtzeitig Bescheid.", "topic": "Onlineshop", "alt_questions": []}}'::jsonb),
  ('web-webshop-keszites-6', 'Mi van, ha nő a bolt?', 'Erre épül. Új nyelv, új piac, új fizetési mód vagy egy raktárintegráció később is rákerülhet, mert kódból van és nem egy sablon korlátain belül mozog. Nem kell mindent az elején eldöntened.', '{"en": {"question": "What if the store grows?", "answer": "It is built for that. A new language, a new market, a new payment method or a warehouse integration can be added later, because it is code and not bounded by a template. You do not have to decide everything at the start.", "topic": "Online shop", "alt_questions": []}, "de": {"question": "Was, wenn der Shop wächst?", "answer": "Dafür ist er gebaut. Eine neue Sprache, ein neuer Markt, eine neue Zahlungsart oder eine Lageranbindung lassen sich später ergänzen, weil er aus Code besteht und nicht an eine Vorlage gebunden ist.", "topic": "Onlineshop", "alt_questions": []}}'::jsonb),
  ('portal-hol-adom-le', 'Hol adhatom le a képeket, a logót és a szövegeket?', 'A portál „Nyersanyag leadása” menüpontjában. Ha több projekted van, először válaszd ki a projektet, majd húzd a fájlokat a kijelölt területre, vagy nyomd meg a „Fájlok kiválasztása” gombot. A leadott fájlok a projekt „Ügyféltől érkezett nyersanyagok” mappájába kerülnek; csak te és a Stratos látja őket, más ügyfél nem.', '{"en": {"question": "Where do I hand over photos, the logo and texts?", "answer": "In the portal''s “Hand over materials” section. If you have several projects, choose the project first, then drag the files onto the marked area or press “Choose files”. Handed-over files go into the project''s “Ügyféltől érkezett nyersanyagok” (materials from the client) folder; only you and Stratos can see them, no other client.", "topic": "Client portal – uploads", "alt_questions": ["where do I upload files", "where can I upload", "how do I send the logo", "upload photos", "hand over texts", "hand over materials", "materials", "where do I upload the logo", "upload the logo and photos", "where do I send the texts"]}, "de": {"question": "Wo gebe ich Fotos, das Logo und Texte ab?", "answer": "Im Portal unter „Material übergeben“. Wenn du mehrere Projekte hast, wähle zuerst das Projekt, dann ziehe die Dateien in den markierten Bereich oder klicke auf „Dateien auswählen“. Übergebene Dateien landen im Ordner „Ügyféltől érkezett nyersanyagok“ (Material vom Kunden) des Projekts; nur du und Stratos sehen sie, kein anderer Kunde.", "topic": "Kundenportal – Hochladen", "alt_questions": ["wo lade ich dateien hoch", "wo kann ich hochladen", "wie schicke ich das logo", "fotos hochladen", "texte abgeben", "material abgeben", "material", "wo lade ich das logo hoch", "logo und fotos hochladen", "wohin schicke ich die texte"]}}'::jsonb),
  ('portal-fajltipusok', 'Milyen fájlokat tölthetek fel?', 'Fájlonként legfeljebb 50 MB. Elfogadott típusok: PDF, Word/Excel/PowerPoint, szöveg és CSV, képek (PNG, JPG, GIF, WebP, TIFF, HEIC, SVG), PSD/AI/EPS, MP4/MOV/MP3 és ZIP. A fájlt a tartalma alapján ellenőrizzük, ezért egy átnevezett fájl (például .exe .pdf-re átírva) nem tölthető fel. Egyszerre legfeljebb 10 feltöltés lehet folyamatban, naponta legfeljebb 200 fájl és 2 GB. Vírusellenőrzés nincs.', '{"en": {"question": "Which files can I upload?", "answer": "Up to 50 MB per file. Accepted types: PDF, Word/Excel/PowerPoint, text and CSV, images (PNG, JPG, GIF, WebP, TIFF, HEIC, SVG), PSD/AI/EPS, MP4/MOV/MP3 and ZIP. Each file is checked by its content, so a renamed file (for example an .exe renamed to .pdf) cannot be uploaded. At most 10 uploads can run at once, and at most 200 files and 2 GB per day. There is no virus scan.", "topic": "Client portal – uploads", "alt_questions": ["how big a file can I upload", "what is the maximum size", "which format", "accepted file types", "can I upload a video", "upload a zip", "the file is too large"]}, "de": {"question": "Welche Dateien kann ich hochladen?", "answer": "Bis zu 50 MB pro Datei. Erlaubte Typen: PDF, Word/Excel/PowerPoint, Text und CSV, Bilder (PNG, JPG, GIF, WebP, TIFF, HEIC, SVG), PSD/AI/EPS, MP4/MOV/MP3 und ZIP. Jede Datei wird anhand ihres Inhalts geprüft, eine umbenannte Datei (zum Beispiel eine in .pdf umbenannte .exe) lässt sich also nicht hochladen. Höchstens 10 Uploads gleichzeitig, höchstens 200 Dateien und 2 GB pro Tag. Es gibt keinen Virenscan.", "topic": "Kundenportal – Hochladen", "alt_questions": ["wie groß darf die datei sein", "was ist die maximale größe", "welches format", "erlaubte dateitypen", "kann ich ein video hochladen", "zip hochladen", "die datei ist zu groß"]}}'::jsonb),
  ('portal-javitott-valtozat', 'Hogyan adhatok le egy javított változatot?', 'Töltsd fel az új változatot új fájlként a „Nyersanyag leadása” menüpontban. Egy már leadott fájlt nem lehet törölni, átnevezni vagy felülírni; ha ugyanazzal a névvel töltesz fel, a portál sorszámot tesz a nevéhez (például „logo (2).png”), így mindkét változat megmarad.', '{"en": {"question": "How do I hand over a corrected version?", "answer": "Upload the new version as a new file under “Hand over materials”. A file you have already handed over cannot be deleted, renamed or overwritten; if you upload one with the same name, the portal adds a number to it (for example “logo (2).png”), so both versions are kept.", "topic": "Client portal – uploads", "alt_questions": ["can I overwrite an uploaded file", "I uploaded the wrong file", "can I delete an upload", "upload a new version", "can I replace the photo", "send a corrected version", "hand over a changed file", "updated material", "replace an earlier photo"]}, "de": {"question": "Wie gebe ich eine korrigierte Version ab?", "answer": "Lade die neue Version als neue Datei unter „Material übergeben“ hoch. Eine bereits übergebene Datei kann nicht gelöscht, umbenannt oder überschrieben werden; lädst du eine mit demselben Namen hoch, hängt das Portal eine Nummer an (zum Beispiel „logo (2).png“), sodass beide Versionen erhalten bleiben.", "topic": "Kundenportal – Hochladen", "alt_questions": ["kann ich eine hochgeladene datei überschreiben", "ich habe die falsche datei hochgeladen", "kann ich einen upload löschen", "neue version hochladen", "kann ich das bild ersetzen", "korrigierte version schicken", "geänderte datei abgeben", "aktualisiertes material", "früheres bild ersetzen"]}}'::jsonb),
  ('portal-dokumentumok-demo', 'Hol találom a megosztott dokumentumokat és a demót?', 'A veled megosztott fájlok a „Megosztott dokumentumok” menüpontban vannak, projektenként csoportosítva; a „Letöltés” gomb egy percig érvényes letöltési linket készít. A közzétett demók a „Projektjeim” oldalon, a projekted kártyáján jelennek meg „Demó megtekintése” gombbal, amely új lapon nyitja meg a demót.', '{"en": {"question": "Where do I find the shared documents and the demo?", "answer": "Files shared with you are under “Shared documents”, grouped by project; the “Download” button creates a download link that is valid for one minute. Published demos appear on the “My projects” page, on your project''s card, with a “View demo” button that opens the demo in a new tab.", "topic": "Client portal – documents and demo", "alt_questions": ["where are the files", "where is the demo", "where can I see the site", "download", "shared materials", "demo link"]}, "de": {"question": "Wo finde ich die geteilten Dokumente und die Demo?", "answer": "Mit dir geteilte Dateien findest du unter „Geteilte Dokumente“, nach Projekt gruppiert; die Schaltfläche „Herunterladen“ erstellt einen Download-Link, der eine Minute gültig ist. Veröffentlichte Demos erscheinen auf der Seite „Meine Projekte“ auf der Karte deines Projekts, mit der Schaltfläche „Demo ansehen“, die die Demo in einem neuen Tab öffnet.", "topic": "Kundenportal – Dokumente und Demo", "alt_questions": ["wo sind die dateien", "wo ist die demo", "wo kann ich die seite ansehen", "herunterladen", "geteilte unterlagen", "demo link"]}}'::jsonb),
  ('portal-demo-visszajelzes', 'Hogyan jelezzek vissza a demóról?', 'A demó kártyáján az „Észrevételek” gombbal írhatsz visszajelzést a demóról. Az üzeneted a Stratos portálján jelenik meg, és a kártyán látod, mikor olvasta el. Munkanapokon 1 munkanapon belül reagálunk.', '{"en": {"question": "How do I give feedback on the demo?", "answer": "Use the “Feedback” button on the demo''s card to write your feedback on the demo. Your message appears in Stratos''s portal, and the card shows you when it has been read. On working days we respond within 1 working day.", "topic": "Client portal – documents and demo", "alt_questions": ["feedback on the demo", "how do I send a comment", "I like the demo, what now", "I found a mistake in the demo", "I want a change in the demo", "feedback", "where do I write my opinion about the demo"]}, "de": {"question": "Wie gebe ich Rückmeldung zur Demo?", "answer": "Über die Schaltfläche „Rückmeldungen“ auf der Karte der Demo kannst du deine Rückmeldung zur Demo schreiben. Deine Nachricht erscheint im Portal von Stratos, und auf der Karte siehst du, wann sie gelesen wurde. An Werktagen reagieren wir innerhalb von 1 Werktag.", "topic": "Kundenportal – Dokumente und Demo", "alt_questions": ["rückmeldung zur demo", "wie schicke ich eine anmerkung", "die demo gefällt mir was nun", "ich habe einen fehler in der demo gefunden", "ich möchte eine änderung an der demo", "rückmeldungen", "wo schreibe ich meine meinung zur demo"]}}'::jsonb),
  ('portal-kovetkezo-megbeszeles', 'Hol látom a következő megbeszélést?', 'A „Projektjeim” oldalon, a projekted kártyáján. A legközelebbi, le nem mondott időpont kiemelten látszik, alatta a további jövőbeli időpontok. A lemondott megbeszélés „Lemondva” jelölést kap. A múltbeli időpontok nem jelennek meg.', '{"en": {"question": "Where can I see the next meeting?", "answer": "On the “My projects” page, on your project''s card. The next meeting that has not been cancelled is highlighted, with the later ones below it. A cancelled meeting is marked “Cancelled”. Past meetings are not shown.", "topic": "Client portal – meetings", "alt_questions": ["when is the next meeting", "where is the appointment", "meeting time", "next meeting", "when do we meet"]}, "de": {"question": "Wo sehe ich den nächsten Termin?", "answer": "Auf der Seite „Meine Projekte“, auf der Karte deines Projekts. Der nächste nicht abgesagte Termin ist hervorgehoben, darunter die weiteren. Ein abgesagter Termin ist mit „Abgesagt“ markiert. Vergangene Termine werden nicht angezeigt.", "topic": "Kundenportal – Termine", "alt_questions": ["wann ist der nächste termin", "wo ist der termin", "uhrzeit des termins", "nächstes meeting", "wann besprechen wir uns"]}}'::jsonb),
  ('portal-naptarba', 'Hogyan tehetem be a naptáramba?', 'A megbeszélés mellett a „Google Naptárba helyezés” gomb új lapon megnyitja a Google Naptár eseménylétrehozó oldalát, a cím, a kezdés, a befejezés, a helyszín vagy a csatlakozási link és a leírás kitöltve; csak mentened kell. Fontos: ha az időpont később a portálon módosul, a korábban elmentett naptárbejegyzés nem frissül magától – a módosítás után mentsd el újra, és a régit töröld.', '{"en": {"question": "How do I add it to my calendar?", "answer": "Next to the meeting, the “Add to Google Calendar” button opens Google Calendar''s new-event page in a new tab, with the title, start, end, place or joining link and description filled in; you only need to save it. Important: if the time later changes in the portal, the calendar entry you saved earlier does not update by itself – save it again after the change and delete the old one.", "topic": "Client portal – meetings", "alt_questions": ["google calendar", "save to calendar", "reminder about the meeting", "how do I save the appointment", "calendar"]}, "de": {"question": "Wie trage ich ihn in meinen Kalender ein?", "answer": "Neben dem Termin öffnet die Schaltfläche „Zu Google Kalender hinzufügen“ in einem neuen Tab die Seite zum Erstellen eines Termins in Google Kalender, mit Titel, Beginn, Ende, Ort oder Teilnahme-Link und Beschreibung bereits ausgefüllt; du musst nur speichern. Wichtig: Ändert sich die Zeit später im Portal, aktualisiert sich der früher gespeicherte Kalendereintrag nicht von selbst – speichere ihn nach der Änderung erneut und lösche den alten.", "topic": "Kundenportal – Termine", "alt_questions": ["google kalender", "im kalender speichern", "erinnerung an den termin", "wie speichere ich den termin", "kalender"]}}'::jsonb),
  ('portal-masik-idopont', 'Hogyan kérhetek másik időpontot?', 'A megbeszélés kártyáján az „Új időpont javaslása” gombbal adhatsz meg másik időpontot, üzenettel együtt. A javaslat a Stratoshoz kerül: ha elfogadjuk, a megbeszélés a portálon az új időpontra módosul; ha nem, a kártyán látod a választ. Amíg a javaslatod függőben van, visszavonhatod. Munkanapokon 1 munkanapon belül reagálunk. A korábban naptárba mentett időpontot az elfogadás után mentsd el újra.', '{"en": {"question": "How can I ask for a different time?", "answer": "Use the “Propose a new time” button on the meeting''s card to suggest another time, with a message. The proposal goes to Stratos: if we accept it, the meeting moves to the new time in the portal; if not, you see the answer on the card. While your proposal is pending you can withdraw it. On working days we respond within 1 working day. If you saved the time in your calendar earlier, save it again once it has been accepted.", "topic": "Client portal – meetings", "alt_questions": ["the time does not suit me", "can we move the meeting", "change the time", "I cancel the meeting", "another day", "I propose a new time", "can I change the time"]}, "de": {"question": "Wie kann ich eine andere Zeit vorschlagen?", "answer": "Über die Schaltfläche „Neue Zeit vorschlagen“ auf der Karte des Termins kannst du eine andere Zeit vorschlagen, mit einer Nachricht. Der Vorschlag geht an Stratos: Nehmen wir ihn an, wird der Termin im Portal auf die neue Zeit verschoben; wenn nicht, siehst du die Antwort auf der Karte. Solange dein Vorschlag offen ist, kannst du ihn zurückziehen. An Werktagen reagieren wir innerhalb von 1 Werktag. Einen früher im Kalender gespeicherten Termin speichere nach der Annahme bitte erneut.", "topic": "Kundenportal – Termine", "alt_questions": ["die zeit passt mir nicht", "können wir den termin verschieben", "termin ändern", "ich sage den termin ab", "anderer tag", "ich schlage eine neue zeit vor", "kann ich die zeit ändern"]}}'::jsonb),
  ('portal-belepes', 'Mit tegyek, ha nem tudok belépni?', 'A belépési oldalon válaszd a „Forgotten your password?” linket, add meg az e-mail-címedet, és a kapott levélben lévő linkkel új jelszót állíthatsz be (legalább 12 karakter). Ha a meghívólinked nem működik (lejárt vagy már felhasználták), kérj újat a Stratostól: a meghívólink egyszer használható és korlátozott ideig érvényes.', '{"en": {"question": "What should I do if I cannot sign in?", "answer": "On the sign-in page choose the “Forgotten your password?” link, enter your e-mail address, and with the link in the e-mail you receive you can set a new password (at least 12 characters). If your invitation link does not work (it has expired or has already been used), ask Stratos for a new one: an invitation link can be used once and is valid for a limited time.", "topic": "Client portal – sign-in and problems", "alt_questions": ["I forgot my password", "I cannot sign in", "the link has expired", "reset my password", "the invitation does not work"]}, "de": {"question": "Was tun, wenn ich mich nicht anmelden kann?", "answer": "Wähle auf der Anmeldeseite den Link „Passwort vergessen?“, gib deine E-Mail-Adresse ein, und mit dem Link in der E-Mail, die du bekommst, kannst du ein neues Passwort festlegen (mindestens 12 Zeichen). Wenn dein Einladungslink nicht funktioniert (abgelaufen oder bereits benutzt), bitte Stratos um einen neuen: Ein Einladungslink ist nur einmal verwendbar und nur begrenzt gültig.", "topic": "Kundenportal – Anmeldung und Probleme", "alt_questions": ["ich habe mein passwort vergessen", "ich kann mich nicht anmelden", "der link ist abgelaufen", "passwort zurücksetzen", "die einladung funktioniert nicht"]}}'::jsonb),
  ('portal-feltoltes-hiba', 'Mit tegyek, ha nem sikerül a feltöltés?', 'A portál minden fájlnál kiírja a hiba okát. Ha a fájl túl nagy (50 MB felett) vagy a típusa nem engedélyezett, más formátumban vagy tömörítve próbáld. Hálózati hiba esetén a fájl mellett megjelenő „Újra” gombbal újraindíthatod; a félbeszakadt feltöltés nem kerül a leadott fájlok közé. Ha a hiba szerint nincs hozzáférésed a projekthez, keresd a Stratost.', '{"en": {"question": "What should I do if an upload fails?", "answer": "The portal shows the reason for each file. If the file is too large (over 50 MB) or its type is not allowed, try another format or a compressed file. After a network error you can restart it with the “Retry” button next to the file; an interrupted upload is not added to your handed-over files. If the error says you have no access to the project, contact Stratos.", "topic": "Client portal – sign-in and problems", "alt_questions": ["it does not upload", "error while uploading", "the upload got stuck", "upload failed", "I have no access"]}, "de": {"question": "Was tun, wenn das Hochladen fehlschlägt?", "answer": "Das Portal zeigt bei jeder Datei den Grund an. Ist die Datei zu groß (über 50 MB) oder ihr Typ nicht erlaubt, versuche es in einem anderen Format oder komprimiert. Nach einem Netzwerkfehler kannst du sie mit der Schaltfläche „Erneut“ neben der Datei neu starten; ein abgebrochener Upload landet nicht bei den übergebenen Dateien. Wenn der Fehler besagt, dass du keinen Zugriff auf das Projekt hast, wende dich an Stratos.", "topic": "Kundenportal – Anmeldung und Probleme", "alt_questions": ["es lädt nicht hoch", "fehler beim hochladen", "der upload hängt", "upload fehlgeschlagen", "ich habe keinen zugriff"]}}'::jsonb),
  ('portal-tovabbi-modositas', 'Hogyan kérhetek további módosítást vagy átadás utáni segítséget?', 'A módosítási körök száma a szerződésedben található. A további módosítás díja a módosítás mértékétől függ. Karbantartásra projekttől függően havidíjas árat adunk. Írj nekünk (lukacs.artur@media-stratos.com, +36 30 584 8024); munkanapokon 1 munkanapon belül válaszolunk.', '{"en": {"question": "How can I ask for further changes or help after the handover?", "answer": "The number of revision rounds is in your contract. The fee for further changes depends on their extent. For maintenance we offer a monthly price depending on the project. Write to us (lukacs.artur@media-stratos.com, +36 30 584 8024); on working days we reply within 1 working day.", "topic": "Client portal – changes and support", "alt_questions": ["further changes", "I would like a change", "help after the handover", "maintenance", "how many revision rounds are there", "warranty"]}, "de": {"question": "Wie bekomme ich weitere Änderungen oder Hilfe nach der Übergabe?", "answer": "Die Anzahl der Korrekturrunden steht in deinem Vertrag. Die Kosten für weitere Änderungen hängen von deren Umfang ab. Für die Wartung bieten wir je nach Projekt einen monatlichen Preis an. Schreib uns (lukacs.artur@media-stratos.com, +36 30 584 8024); an Werktagen antworten wir innerhalb von 1 Werktag.", "topic": "Kundenportal – Änderungen und Support", "alt_questions": ["weitere änderungen", "ich möchte etwas ändern", "hilfe nach der übergabe", "wartung", "wie viele korrekturrunden gibt es", "garantie"]}}'::jsonb),
  ('portal-ki-latja', 'Ki látja a feltöltött és a velem megosztott fájlokat?', 'A te feltöltéseidet csak te és a Stratos látja; ugyanazon a projekten dolgozó más ügyfél sem. A megosztott fájlt csak az látja, akivel megosztották. Ha a projekthez való hozzáférésedet visszavonják, a projekt, a megosztások, a demók és a megbeszélések is eltűnnek a portálodról.', '{"en": {"question": "Who can see the files I upload and the files shared with me?", "answer": "Only you and Stratos can see your uploads; not even another client working on the same project. A shared file is visible only to the person it was shared with. If your access to the project is withdrawn, the project, its shares, demos and meetings disappear from your portal.", "topic": "Client portal – documents and demo", "alt_questions": ["can others see my files", "is uploading safe", "who has access", "data protection"]}, "de": {"question": "Wer sieht die von mir hochgeladenen und die mit mir geteilten Dateien?", "answer": "Deine Uploads sehen nur du und Stratos; auch kein anderer Kunde im selben Projekt. Eine geteilte Datei sieht nur, wer sie geteilt bekommen hat. Wird dein Zugriff auf das Projekt entzogen, verschwinden das Projekt, die Freigaben, die Demos und die Termine aus deinem Portal.", "topic": "Kundenportal – Dokumente und Demo", "alt_questions": ["können andere meine dateien sehen", "ist das hochladen sicher", "wer hat zugriff", "datenschutz"]}}'::jsonb),
  ('portal-demo-nyilvanos', 'Csak én látom a demóoldalt?', 'A portálon csak a projektedhez rendelt fiókok látják a demó linkjét, de maga a demóoldal a portálon kívül fut: aki ismeri a címét, az meg tudja nyitni. Ezért a demó linkjét ne add tovább olyannak, akinek nem szánod.', '{"en": {"question": "Am I the only one who can see the demo site?", "answer": "In the portal only the accounts assigned to your project see the demo''s link, but the demo site itself runs outside the portal: anyone who knows its address can open it. So do not pass the demo link on to anyone it is not meant for.", "topic": "Client portal – documents and demo", "alt_questions": ["is the demo private", "can I share the demo", "is the demo password-protected", "who can see the demo"]}, "de": {"question": "Sehe nur ich die Demo-Seite?", "answer": "Im Portal sehen nur die deinem Projekt zugeordneten Konten den Link zur Demo, die Demo-Seite selbst läuft aber außerhalb des Portals: Wer ihre Adresse kennt, kann sie öffnen. Gib den Demo-Link deshalb nicht an Personen weiter, für die er nicht gedacht ist.", "topic": "Kundenportal – Dokumente und Demo", "alt_questions": ["ist die demo privat", "kann ich die demo teilen", "ist die demo passwortgeschützt", "wer sieht die demo"]}}'::jsonb),
  ('portal-projekt-allapot', 'Hol látom a projekt állapotát, határidejét vagy a fizetéseket?', 'A portál ügyféloldalán nincs projektállapot, határidő vagy pénzügyi információ: itt a megosztott dokumentumokat, a közzétett demókat, a következő megbeszéléseket és a saját feltöltéseidet látod. A projekt állásáról a Stratos kapcsolattartódtól kérdezz.', '{"en": {"question": "Where can I see the project''s status, deadline or payments?", "answer": "The client side of the portal shows no project status, deadline or financial information: here you see shared documents, published demos, upcoming meetings and your own uploads. Ask your Stratos contact about how the project is going.", "topic": "Client portal – changes and support", "alt_questions": ["how far along is the project", "when will it be ready", "deadline", "invoice", "payment", "how much have I paid", "project status"]}, "de": {"question": "Wo sehe ich den Projektstatus, die Frist oder die Zahlungen?", "answer": "Die Kundenseite des Portals zeigt keinen Projektstatus, keine Fristen und keine Finanzinformationen: Hier siehst du geteilte Dokumente, veröffentlichte Demos, kommende Termine und deine eigenen Uploads. Frag deinen Ansprechpartner bei Stratos, wie das Projekt steht.", "topic": "Kundenportal – Änderungen und Support", "alt_questions": ["wie weit ist das projekt", "wann ist es fertig", "frist", "rechnung", "zahlung", "wie viel habe ich bezahlt", "projektstatus"]}}'::jsonb)
  ) as s(slug, question, answer, tr)
 where h.slug = s.slug
   and h.question = s.question
   and h.answer = s.answer
   and h.translations = '{}'::jsonb;
